using System;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
static class BatchAppsView {
 public static FrameworkElement Build(){var body=new StackPanel();var status=RiceLayout.Hint("Type to filter, check apps and save the list. /openall opens these apps; existing app rules control placement.");body.Children.Add(status);BatchAppSettings settings;try{settings=BatchAppSettings.Load();}catch{settings=new BatchAppSettings();}var apps=AppCatalog.Load().OrderBy(a=>a.Name).ToArray();var selected=new HashSet<string>(settings.appIds??new string[0],StringComparer.OrdinalIgnoreCase);foreach(var app in apps.Where(settings.Includes))selected.Add(app.Key);var legacy=new HashSet<string>((settings.apps??new string[0]).Where(n=>!apps.Any(a=>String.Equals(a.Name,n,StringComparison.OrdinalIgnoreCase))),StringComparer.OrdinalIgnoreCase);var search=new TextBox{Margin=new Thickness(0,0,0,8),ToolTip="Filter installed apps"};body.Children.Add(search);var list=new StackPanel();var rows=new List<CheckBox>();foreach(var app in apps){var entry=app;var box=new CheckBox{Content=app.Name,IsChecked=selected.Contains(app.Key),Tag=app.Name,Margin=new Thickness(2,4,2,4),Foreground=ControlCenterTheme.Current.Brush("Text")};box.Checked+=delegate{selected.Add(entry.Key);};box.Unchecked+=delegate{selected.Remove(entry.Key);};rows.Add(box);list.Children.Add(box);}foreach(var missing in selected.Where(id=>!apps.Any(a=>a.Key==id)).Concat(legacy).ToArray()){var name=missing;bool legacyName=legacy.Contains(name);var box=new CheckBox{Content=name+" (not installed)",IsChecked=true,Tag=name,Margin=new Thickness(2,4,2,4),Foreground=ControlCenterTheme.Current.Brush("Muted")};box.Checked+=delegate{if(legacyName)legacy.Add(name);else selected.Add(name);};box.Unchecked+=delegate{if(legacyName)legacy.Remove(name);else selected.Remove(name);};rows.Add(box);list.Children.Add(box);}search.TextChanged+=delegate{foreach(var row in rows)row.Visibility=((string)row.Tag).IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0?Visibility.Visible:Visibility.Collapsed;};var scroll=new ScrollViewer{Content=list,Height=180,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};scroll.SetResourceReference(FrameworkElement.StyleProperty,"RiceScrollViewer");body.Children.Add(scroll);var save=RiceLayout.Button("Save app list","RiceSaveOpenAll");save.Margin=new Thickness(0,8,0,0);save.Click+=delegate{try{BatchAppSettings.Save(selected.ToArray(),legacy.ToArray());status.Text="Saved. /openall uses this list; /closeall uses live workspace taskbar windows.";}catch(Exception ex){status.Text=ex.Message;}};body.Children.Add(save);body.Children.Add(RiceLayout.Hint("/closeall requests normal closes across workspace taskbars. Apps can show save prompts or keep running in the tray; nothing is force-killed."));return new Expander{Header="Spotlight: /openall apps",Content=body,Margin=new Thickness(0,12,0,0)};}
}
